import re
from auto_config.generator.vcu.managed_objects.managed_object import ManagedObject


class VlanifParamsGenerator(ManagedObject):

    def _prepare_section_content(self, execution_config, *args, **kwargs):

        # self.set_parameter('ipAddressAllocationMethod', 'DISCOVERED')
        self.set_vlanIfName()

    def set_vlanIfName(self):
        srch = re.search(r"TNL-(\d+)/ETHSVC-1/ETHIF-1/VLANIF-(\d+)", self.dist_name)
        tnl_num = srch.group(1)
        vlanif_num = srch.group(2)

        if tnl_num == '1' or tnl_num == '4':
            self.set_parameter('vlanIfName', 'oamvlan')

        elif (tnl_num == '2' or tnl_num == '5') and vlanif_num == '1':
            self.set_parameter('vlanIfName', 'ngc')
        elif (tnl_num == '2' or tnl_num == '5') and vlanif_num == '2':
            self.set_parameter('vlanIfName', 'f1c')
        elif (tnl_num == '2' or tnl_num == '5') and vlanif_num == '3':
            self.set_parameter('vlanIfName', 'xnc')
        elif (tnl_num == '2' or tnl_num == '5') and vlanif_num == '4':
            self.set_parameter('vlanIfName', 'x2c')

        elif (tnl_num == '3' or tnl_num == '6') and vlanif_num == '1':
            self.set_parameter('vlanIfName', 'ngu')
        elif (tnl_num == '3' or tnl_num == '6') and vlanif_num == '2':
            self.set_parameter('vlanIfName', 'f1u')
        elif (tnl_num == '3' or tnl_num == '6') and vlanif_num == '3':
            self.set_parameter('vlanIfName', 'xnu')
        elif (tnl_num == '3' or tnl_num == '6') and vlanif_num == '4':
            self.set_parameter('vlanIfName', 'x2u')

        self.set_tnl_conf(tnl_num, vlanif_num)

    def set_tnl_conf(self, tnl_num, vlanif_num):
        if self.enb_ent_config.get('tnl_conf'):
            param_value = ''
            dn_found = False
            for interface, dn in self.enb_ent_config.get('tnl_conf').items():
                custom_srch = re.search(r"TNL-(\d+)/IPNO-1/IPIF-(\d+)", dn)
                custom_tnl_num = custom_srch.group(1)
                custom_ipif_num = custom_srch.group(2)
                if custom_tnl_num == tnl_num and custom_ipif_num == vlanif_num:
                    dn_found = True
                    param_value += ' ' + interface
            if dn_found:
                self.set_parameter('vlanIfName', param_value.strip())
